/** Nonces are generated by the proxy, never accepted from incoming headers. */
export function contentSecurityPolicy(nonce: string, supabaseUrl?: string, development = false) {
  let apiOrigin = "";
  try {
    const url = new URL(supabaseUrl ?? "");
    if (url.protocol === "https:" || (url.protocol === "http:" && ["127.0.0.1", "localhost"].includes(url.hostname))) {
      apiOrigin = url.origin;
    }
  } catch { /* Missing configuration does not widen the policy. */ }
  return [
    "default-src 'self'",
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${development ? " 'unsafe-eval'" : ""}`,
    // Radix and dynamic positioning use inline style attributes.
    "style-src 'self' 'unsafe-inline'",
    // Legacy shop logos may have external HTTPS URLs.
    "img-src 'self' https: data: blob:" + (apiOrigin.startsWith("http:") ? " " + apiOrigin : ""),
    "font-src 'self'",
    `connect-src 'self'${apiOrigin ? " " + apiOrigin : ""}${development ? " ws: wss:" : ""}`,
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'none'",
    "frame-src 'none'",
  ].join("; ");
}

// Safe baseline while the complete script/connect policy is homologated.
export const baselineCsp = "object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'";
